void KeyboardBacklightProviderAsyncWaiter::ShouldShowNudge(
    bool* out_should_show_nudge) {
  base::RunLoop loop;
  proxy_->ShouldShowNudge(
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_should_show_nudge
,
             bool should_show_nudge) {*out_should_show_nudge = std::move(should_show_nudge);
            loop->Quit();
          },
          &loop,
          out_should_show_nudge));
  loop.Run();
}

